      return unrecognized(raw, 'Rocket Recall is excluded from this application.');
    if (activity === 'c3l6-organic-reactions')
      return course === 'alevel'
        ? { kind: 'olympiad', activityId: 'alevel/c3l6-organic-reactions', source: raw }
