/* One viewport theme. Card/editor surfaces remain local; immutable image assets stay untouched. */
body{min-height:100vh;isolation:isolate;background:var(--app-background);background-attachment:fixed}
body::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;opacity:.45;background-image:radial-gradient(circle,#fff 1px,transparent 1.5px),radial-gradient(circle,#55f6ff 1px,transparent 1.5px);background-position:0 0,31px 37px;background-size:74px 74px,101px 101px;mask-image:linear-gradient(to bottom,black,transparent 92%)}
/* !important also covers SVG presentation attributes, lazy source CSS and native form defaults. */
:root *,:root *::before,:root *::after{font-family:var(--ui-font-family)!important}
/* Only spin-arrow glyphs need a symbol fallback if Comfortaa lacks that code point. */
:root .ec-box,:root .ec-source .orbital{font-family:Comfortaa,'Segoe UI Symbol',sans-serif!important}
.original-landing.alevel .stars,.original-landing.igcse .stars{display:none}
.course-shell,.course-question-screen,.original-landing.alevel,.original-landing.igcse,.landing-course-stage{background:transparent}
.course-question-screen .course-layout{max-width:var(--question-pane-max-width);margin-inline:auto}
@media print{body{background:#fff}body::before{display:none}}

