                  type="button"
                  disabled={readOnly}
                  aria-label={`Remove selection ${index + 1}`}
                  onClick={() =>
                    onResponse({
                      ...current,
                      selections: current.selections.filter((_, item) => item !== index),
                    })
                  }
                >
                  Remove
                </button>
              </li>
            ))}
          </ul>
